def _views(study, z):
    from scipy.optimize import minimize_scalar
    c = study['panel_c']
    u = c['u']
    p = _affine(_cyclic(z)) @ _fit(_affine(_cyclic(u)), c['v1'])

    def f(x, k):
        return np.c_[_affine(x), np.log1p(k * x * x)]

    def loss(k):
        g = f(u, k)
        return np.mean((g @ _fit(g, c['v2']) - c['v2']) ** 2)
    k = minimize_scalar(loss, bounds=(0.05, 1.5), method='bounded').x
    q = f(z, k) @ _fit(f(u, k), c['v2'])
    return (p, q)

def _invert(x, coef):
    from scipy.optimize import least_squares
    (c0, c1, c2, c3, c4) = coef

    def residual(z, observed):
        zn = np.roll(z, -1)
        return c0 + c1 * z + c2 * zn + c3 * z * zn + c4 * z ** 3 - observed

    def jac(z, observed):
        d = np.diag(c1 + c3 * np.roll(z, -1) + 3 * c4 * z * z)
        d[np.arange(4), np.roll(np.arange(4), -1)] = c2 + c3 * z
        return d
    return np.array([least_squares(residual, (row - c0) / c1, jac=jac, args=(row,), gtol=1e-12, ftol=1e-12, xtol=1e-12).x for row in x])

def _design(study, x):
    z = _invert(x, _calibrate(study['panel_a']))
    (b, p, q) = _views(study, z)
    return np.column_stack((z, p, q, _outer(b, p), _outer(p, q)))
